fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(8, (cx - 120) * 16);
        host::display::state_set(9, (cy - 60) * 16);
        host::display::state_set(10, 30);
        host::display::state_set(11, 10);
        host::display::state_set(12, (cx + 130) * 16);
        host::display::state_set(13, (cy - 40) * 16);
        host::display::state_set(14, -20);
        host::display::state_set(15, 25);
        host::display::state_set(16, (cx - 10) * 16);
        host::display::state_set(17, (cy + 110) * 16);
        host::display::state_set(18, -10);
        host::display::state_set(19, -35);
    }
    let mut x = [0; 3];
    let mut y = [0; 3];
    let mut vx = [0; 3];
    let mut vy = [0; 3];
    let mut i: i32 = 0;
    while i < 3 {
        x[i] = host::display::state_get(8 + i * 4);
        y[i] = host::display::state_get(9 + i * 4);
        vx[i] = host::display::state_get(10 + i * 4);
        vy[i] = host::display::state_get(11 + i * 4);
        i = i + 1;
    }
    i = 0;
    while i < 3 {
        let mut j: i32 = 0;
        while j < 3 {
            if j != i {
                vx[i] = vx[i] + (x[j] - x[i]) / 512;
                vy[i] = vy[i] + (y[j] - y[i]) / 512;
            }
            j = j + 1;
        }
        i = i + 1;
    }
    i = 0;
    while i < 3 {
        x[i] = x[i] + vx[i];
        y[i] = y[i] + vy[i];
        if x[i] < 128 { x[i] = 128; vx[i] = -vx[i]; }
        if x[i] > (w - 8) * 16 { x[i] = (w - 8) * 16; vx[i] = -vx[i]; }
        if y[i] < 128 { y[i] = 128; vy[i] = -vy[i]; }
        if y[i] > (h - 8) * 16 { y[i] = (h - 8) * 16; vy[i] = -vy[i]; }
        host::display::state_set(8 + i * 4, x[i]);
        host::display::state_set(9 + i * 4, y[i]);
        host::display::state_set(10 + i * 4, vx[i]);
        host::display::state_set(11 + i * 4, vy[i]);
        i = i + 1;
    }
    host::display::clear(0x060608);
    host::display::draw_line(x[0] / 16, y[0] / 16, x[1] / 16, y[1] / 16, 0x283038);
    host::display::draw_line(x[1] / 16, y[1] / 16, x[2] / 16, y[2] / 16, 0x283038);
    host::display::draw_line(x[2] / 16, y[2] / 16, x[0] / 16, y[0] / 16, 0x283038);
    let pal: [i32; 3] = [0xff7060, 0x70ff90, 0x70a0ff];
    i = 0;
    while i < 3 {
        host::display::fill_rect(x[i] / 16 - 6, y[i] / 16 - 6, 12, 12, pal[i]);
        i = i + 1;
    }
    host::display::present();
}
